    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        if (empty($this->order_products)) {
            $this->command->error('No order products data provided in the array.');
            return;
        }

        \DB::statement('SET FOREIGN_KEY_CHECKS=0;');

        $this->command->info('Starting Order Products migration from array...');
        $this->command->getOutput()->progressStart(count($this->order_products));

        foreach ($this->order_products as $orderr) {
            try {
                \DB::beginTransaction();

                $this->command->info('Processing order id : '.$orderr['order_id']);

                // Create new User
                $OrderItem = new OrderItem();
                $OrderItem->id = $orderr['id'];
                $OrderItem->order_id = $orderr['order_id'];
                $OrderItem->product_id = $orderr['product_id'];
                $OrderItem->product_title = $orderr['product_title'];
                $OrderItem->product_unit_price = $orderr['product_unit_price'];
                $OrderItem->quantity = $orderr['product_quantity'];
                $OrderItem->product_gst_rate = $orderr['product_gst_rate'];
                $OrderItem->product_gst = $orderr['product_gst'];
                $OrderItem->total_price = $orderr['product_total_price'];
                $OrderItem->created_at = $orderr['created_at'];
                $OrderItem->updated_at = $orderr['updated_at'];
                $OrderItem->save();

                \DB::commit();
                $this->command->getOutput()->progressAdvance();
            } catch (\Exception $e) {
                \DB::rollBack();
                $this->command->error("Failed to migrate order" . $e->getMessage());  
            }
        }

        \DB::statement('SET FOREIGN_KEY_CHECKS=1;');

        $this->command->getOutput()->progressFinish();
        $this->command->info('Order Products migration from array completed.');
    }
